        // Tests that different zones create different entries in the cache
        GJChronology utcChrono = GJChronology.getInstance(DateTimeZone.UTC, null, 1);
        GJChronology shanghaiChrono = GJChronology.getInstance(DateTimeZone.forID("Asia/Shanghai"), null, 1);

